&lt;div style=&quot;float: right; padding: 0 0 8px 8px; max-width:300px;&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#B_Pays_natal_Parents_et_Fr&#232;res_et_sœurs_selon_la_race_14&quot;&gt;1. Pays natal, Parents et Fr&#232;res et sœurs selon la race&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Nain_0&quot;&gt;Nain&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Elfe_1&quot;&gt;Elfe&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Gnome_2&quot;&gt;Gnome&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Demi-elfe_3&quot;&gt;Demi-elfe&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Demi-orque_4&quot;&gt;Demi-orque&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Halfelin_5&quot;&gt;Halfelin&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Humain_6&quot;&gt;Humain&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Foyer_inhabituel_7&quot;&gt;Foyer inhabituel&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_fr&#232;res_et_sœurs_8&quot;&gt;Les fr&#232;res et sœurs&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#C_Circonstance_de_la_naissance_et_pr&#233;cisions_sur_les_parents_15&quot;&gt;2. Circonstance de la naissance et pr&#233;cisions sur les parents&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Circonstances_de_la_naissance_9&quot;&gt;Circonstances de la naissance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Profession_des_parents_10&quot;&gt;Profession des parents&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Adopt&#233;_par_des_parents_d’une_autre_race_11&quot;&gt;Adopt&#233; par des parents d’une autre race&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Noblesse_12&quot;&gt;Noblesse&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#D_&#201;v&#232;nement_marquant_de_lenfance_16&quot;&gt;3. &#201;v&#232;nement marquant de l&#39;enfance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Encadr&#233;_:_Crime_et_ch&#226;timent_13&quot;&gt;Encadr&#233; : Crime et ch&#226;timent&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Guide de campagne (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Campaign/Guide de campagne&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoGC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;&lt;i&gt;Retour au &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique.html&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique&quot;&gt;G&#233;n&#233;rateur d&#39;historique&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Les tables de cette section d&#233;finissent votre famille et votre foyer dans les grandes lignes, c’est &#224; dire la mani&#232;re dont vous avez &#233;t&#233; &#233;lev&#233;, la composition de votre famille, votre statut social et un &#233;v&#233;nement marquant de votre enfance. Pour d&#233;terminer ces aspects de votre pass&#233;, suivez les consignes suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;1.&lt;/b&gt; Cherchez les sections qui correspondent &#224; votre race et lancez le d&#233; dans les tables Pays natal, Parents et Fr&#232;res et sœurs. Si vous avez des fr&#232;res et sœurs, consultez aussi les tables &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#AGERELATIFDESFRERESETSOEURS&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;&#194;ge relatif des fr&#232;res et sœurs&lt;/a&gt;&quot; et &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#RACESDESENFANTSADOPTES&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Races des enfants adopt&#233;s&lt;/a&gt;&quot; pour d&#233;terminer leur &#226;ge relatif et leur race s’ils ont &#233;t&#233; adopt&#233;s.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;2.&lt;/b&gt; Lancez le d&#233; dans la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#CIRCONSTANCESDELANAISSANCE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Circonstances de la naissance&lt;/a&gt;&quot;, pour d&#233;terminer les circonstances de votre naissance. En fonction de cela, vous devrez peut-&#234;tre utiliser les tables &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#PROFESSIONDESPARENTS&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Profession des parents&lt;/a&gt;&quot;, &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#ADOPTEPARDESPARENTSDUNEAUTRERACE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Adopt&#233; par des parents d’une autre race&lt;/a&gt;&quot; et &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#NOBLESSE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Noblesse&lt;/a&gt;&quot; pour approfondir quelques d&#233;tails.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;3.&lt;/b&gt; Utilisez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#EVENEMENTMARQUANTDELENFANCE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;&#201;v&#233;nement marquant de l’enfance&lt;/a&gt;&quot; pour d&#233;terminer un &#233;v&#233;nement marquant de votre enfance.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;4.&lt;/b&gt; Passez &#224; l’&#233;tape 2, &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-2.html&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 2: Adolescence et formation&quot;&gt;Adolescence et formation&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;1. Pays natal, Parents et Fr&#232;res et sœurs selon la race&lt;a class=&quot;headeranchor&quot; id=&quot;B_Pays_natal_Parents_et_Fr&#232;res_et_sœurs_selon_la_race_14&quot; href=&quot;#B_Pays_natal_Parents_et_Fr&#232;res_et_sœurs_selon_la_race_14&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Nain&lt;a class=&quot;headeranchor&quot; id=&quot;Nain_0&quot; href=&quot;#Nain_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Beaucoup de nains sont issus de communaut&#233;s industrieuses tr&#232;s soud&#233;es, qui se composent d’individus unis par une m&#234;me tournure d’esprit et d&#233;vou&#233; &#224; l’accomplissement d’un objectif commun.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PAYSNATALNAIN&quot; href=&quot;#PAYSNATALNAIN&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Pays natal nain&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-40&lt;/td&gt;&lt;td&gt;&lt;b&gt;Collines ou montagnes.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; renifleur d’or et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; habitant des hautes terres.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-80&lt;/td&gt;&lt;td&gt;&lt;b&gt;Souterrain.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; combattant des tunnels et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; &#233;tranger &#224; la surface.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-87&lt;/td&gt;&lt;td&gt;&lt;b&gt;Ville ou Village &#233;tranger.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; ma&#238;tre brasseur et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; milicien v&#233;t&#233;ran.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;88-95&lt;/td&gt;&lt;td&gt;&lt;b&gt;Cit&#233; ou capitale &#233;trang&#232;re.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; ma&#238;tre brasseur et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; enfant vagabond.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Foyer inhabituel.&lt;/b&gt; Lancez le d&#233; dans la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#FOYERINHABITUEL&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Foyer inhabituel&lt;/a&gt;&quot;.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PARENTSNAINS&quot; href=&quot;#PARENTSNAINS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Parents nains&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-60&lt;/td&gt;&lt;td&gt;Vos deux parents sont en vie.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-73&lt;/td&gt;&lt;td&gt;Il ne vous reste que votre p&#232;re.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;74-86&lt;/td&gt;&lt;td&gt;Il ne vous reste que votre m&#232;re.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;87-100&lt;/td&gt;&lt;td&gt;Vos deux parents sont d&#233;c&#233;d&#233;s, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; orphelin.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FRERESETSOEURSNAINS&quot; href=&quot;#FRERESETSOEURSNAINS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Fr&#232;res et sœurs nains&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-80&lt;/td&gt;&lt;td&gt;&lt;b&gt;1d4 fr&#232;res et sœurs biologiques.&lt;/b&gt; Si vous en avez deux ou plus, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; protecteur de la famille.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-90&lt;/td&gt;&lt;td&gt;&lt;b&gt;1d4+1 fr&#232;res et sœurs biologiques.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; protecteur de la famille.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91-95&lt;/td&gt;&lt;td&gt;&lt;b&gt;1d3-1 fr&#232;res et sœurs naturels et 1d3-1 adoptifs.&lt;/b&gt; Si vous en avez au moins deux, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; protecteur de la famille. Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#RACESDESENFANTSADOPTES&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Race des enfants adopt&#233;s&lt;/a&gt;&quot; pour d&#233;terminer leur race.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Enfant unique.&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Elfe&lt;a class=&quot;headeranchor&quot; id=&quot;Elfe_1&quot; href=&quot;#Elfe_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les elfes sont souvent &#233;lev&#233;s dans des communaut&#233;s elfiques insulaires. Comme les elfes ont une grande esp&#233;rance de vie, leurs enfants grandissent au sein de familles qui comptent de nombreuses g&#233;n&#233;rations.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PAYSNATALELFIQUE&quot; href=&quot;#PAYSNATALELFIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Pays natal elfique&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-60&lt;/td&gt;&lt;td&gt;&lt;b&gt;For&#234;t.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; draveur.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-80&lt;/td&gt;&lt;td&gt;&lt;b&gt;Cit&#233; ou capitale &#233;trang&#232;re.&lt;/b&gt; Si vous &#234;tes un elfe, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; civilis&#233; et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; d&#233;laiss&#233;. Si vous &#234;tes un demi-elfe, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; civilis&#233; et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; apprenti rat&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-95&lt;/td&gt;&lt;td&gt;&lt;b&gt;Ville ou village &#233;tranger.&lt;/b&gt; Si vous &#234;tes un elfe, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; d&#233;laiss&#233;. Si vous &#234;tes un demi-elfe, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; apprenti rat&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Foyer inhabituel.&lt;/b&gt; Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#FOYERINHABITUEL&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Foyer inhabituel&lt;/a&gt;&quot;. Si vous &#234;tes un elfe, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; d&#233;laiss&#233;. Si vous &#234;tes un demi-elfe, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; r&#233;flexes elfiques.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PARENTSELFIQUES&quot; href=&quot;#PARENTSELFIQUES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Parents elfiques&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-79&lt;/td&gt;&lt;td&gt;Vos deux parents sont en vie.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;80-87&lt;/td&gt;&lt;td&gt;Il ne vous reste que votre p&#232;re.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;88-95&lt;/td&gt;&lt;td&gt;Il ne vous reste que votre m&#232;re.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;Vos deux parents sont d&#233;c&#233;d&#233;s, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; orphelin.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FRERESETSOEURSELFIQUES&quot; href=&quot;#FRERESETSOEURSELFIQUES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Fr&#232;res et sœurs elfiques&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-80&lt;/td&gt;&lt;td&gt;&lt;b&gt;1d2 fr&#232;res et sœurs biologiques.&lt;/b&gt; Si vous en avez deux, vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; protecteur de la famille.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-85&lt;/td&gt;&lt;td&gt;&lt;b&gt;1d4+1 fr&#232;res et sœurs biologiques.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; protecteur de la famille.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;86-90&lt;/td&gt;&lt;td&gt;&lt;b&gt;1d4+1 fr&#232;res et sœurs biologiques.&lt;/b&gt; 1d3-1 sont des demielfes, des adopt&#233;s ou un m&#233;lange des deux (&#224; vous de choisir). Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; protecteur de la famille. Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#RACESDESENFANTSADOPTES&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Race des enfants adopt&#233;s&lt;/a&gt;&quot; pour d&#233;terminer la race des adopt&#233;s.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Enfant unique.&lt;/b&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;&lt;/div&gt;
