&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RACESDESENFANTSADOPTES&quot; href=&quot;#RACESDESENFANTSADOPTES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Races des enfants adopt&#233;s&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;02&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin-(Race).html&quot; title=&quot;Les hommes-f&#233;lins&quot;&gt;Homme-f&#233;lin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;03-04&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;Changelin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;05&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html&quot; title=&quot;Les dhampirs&quot;&gt;Dhampir&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;06&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duergar-(Race).html&quot; title=&quot;Les duergars&quot;&gt;Duergar&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;07-16&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;17-26&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;27&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fetchelin-(Race).html&quot; title=&quot;Les fetchelins&quot;&gt;Fetchelin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;28&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aquatique-(Race).html&quot; title=&quot;Les aquatiques&quot;&gt;Aquatique&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;29-38&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;39&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;40&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grippli-(Race).html&quot; title=&quot;Les gripplis&quot;&gt;Grippli&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-50&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;51-60&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-70&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;72-81&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;82&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ifrit-(Race).html&quot; title=&quot;Les ifrits&quot;&gt;Ifrit&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;83&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kitsune-(Race).html&quot; title=&quot;Les kitsune&quot;&gt;Kitsune&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;84&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;85&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;Homme-poisson&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;86&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nagaji-(Race).html&quot; title=&quot;Les nagajis&quot;&gt;Nagaji&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;87&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;88&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;89&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;90&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Samsaran-(Race).html&quot; title=&quot;Les samsarans&quot;&gt;Samsaran&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Strix-(Race).html&quot; title=&quot;Les strix&quot;&gt;Strix&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;92&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suli-(Race).html&quot; title=&quot;Les sulis&quot;&gt;Suli&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;93&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin-(Race).html&quot; title=&quot;Les svirfneblins&quot;&gt;Svirfneblin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;94&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;95&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;Tengu&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;97&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;98&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vanara-(Race).html&quot; title=&quot;Les vanaras&quot;&gt;Vanara&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;99&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vishkanya-(Race).html&quot; title=&quot;Les vishkanyas&quot;&gt;Vishkanya&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;100&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Wayang-(Race).html&quot; title=&quot;Les wayangs&quot;&gt;Wayang&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;2. Circonstance de la naissance et pr&#233;cisions sur les parents&lt;a class=&quot;headeranchor&quot; id=&quot;C_Circonstance_de_la_naissance_et_pr&#233;cisions_sur_les_parents_15&quot; href=&quot;#C_Circonstance_de_la_naissance_et_pr&#233;cisions_sur_les_parents_15&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Circonstances de la naissance&lt;a class=&quot;headeranchor&quot; id=&quot;Circonstances_de_la_naissance_9&quot; href=&quot;#Circonstances_de_la_naissance_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#CIRCONSTANCESDELANAISSANCE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Circonstances de la naissance&lt;/a&gt;&quot; pour d&#233;terminer les circonstances de votre naissance.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CIRCONSTANCESDELANAISSANCE&quot; href=&quot;#CIRCONSTANCESDELANAISSANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Circonstances de la naissance&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-40&lt;/td&gt;&lt;td&gt;&lt;b&gt;Classe inf&#233;rieure.&lt;/b&gt; Vous &#234;tes n&#233; chez des paysans ou des habitants d’un quartier pauvre. Vous avez grandi en travaillant la terre non loin d’un village ou d’un manoir, en faisant des petits boulots ou en mendiant dans une communaut&#233;. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; mis&#233;reux. Lancez 2d20 et non 1d100 dans la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#PROFESSIONDESPARENTS&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Profession des parents&lt;/a&gt;&quot; : Profession des parents pour d&#233;terminer le m&#233;tier de vos parents.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-65&lt;/td&gt;&lt;td&gt;&lt;b&gt;Classe moyenne.&lt;/b&gt; Vous &#234;tes n&#233; dans la classe moyenne des marchands, des artisans et des commer&#231;ants. Vous avez s&#251;rement grandi dans une communaut&#233; de taille respectable et l’un de vos parents fait s&#251;rement partie d’une guilde ou d’une organisation. Vous &#234;tes libre, vous n’&#234;tes ni serf ni paysan mais vous ne b&#233;n&#233;ficiez pas des privil&#232;ges de la noblesse. Vous avez acc&#232;s aux traits sociaux artisan et marchand.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;66-70&lt;/td&gt;&lt;td&gt;&lt;b&gt;Noble lignage.&lt;/b&gt; Vous &#234;tes n&#233; parmi les privil&#233;gi&#233;s de la noblesse. &#192; moins que l’un de vos parents ne soit r&#233;gent, votre famille sert un noble de plus haut rang mais elle a aussi &#224; son service des nobles de rang inf&#233;rieur. Vous avez acc&#232;s aux traits sociaux influent et parents fortun&#233;s. Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#NOBLESSE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Noblesse&lt;/a&gt;&quot; : Noblesse pour d&#233;terminer le rang de votre famille.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71-72&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des individus qui ne sont pas de votre race.&lt;/b&gt; Vous n’avez pas &#233;t&#233; &#233;lev&#233; par vos parents biologiques mais par une famille d’une autre race que la v&#244;tre. Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#ADOPTEPARDESPARENTSDUNEAUTRERACE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Adopt&#233; par des parents d&#39;une autre race&lt;/a&gt;&quot; : adopt&#233;s par des parents d’une autre race.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;73-77&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233;.&lt;/b&gt; Ce ne sont pas vos parents biologiques qui vous ont &#233;lev&#233; mais une famille de la m&#234;me race et de la m&#234;me culture que la leur. Lancez deux fois le d&#233; dans la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#PROFESSIONDESPARENTS&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Profession des parents&lt;/a&gt;&quot; Profession des parents. Une fois pour votre famille naturelle, une fois pour votre famille d’adoption. Vous avez acc&#232;s aux dons conf&#233;r&#233;s par vos deux couples de parents.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;78-81&lt;/td&gt;&lt;td&gt;&lt;b&gt;B&#226;tard.&lt;/b&gt; Vos parents ont eu une aventure adult&#232;re qui s’est sold&#233;e par votre naissance. Vous connaissez l’un de vos g&#233;niteurs mais l’autre vous est inconnu ou n’est, au mieux, qu’une pr&#233;sence tr&#232;s distante. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; b&#226;tard et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Fruit-De-La-Honte.html&quot; title=&quot;Fruit de la honte&quot;&gt;Fruit de la honte&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;82&lt;/td&gt;&lt;td&gt;&lt;b&gt;Naissance b&#233;nie.&lt;/b&gt; &#192; votre naissance, vous avez re&#231;u la b&#233;n&#233;diction d’un &#234;tre tr&#232;s puissant, comme un ange, un azata ou un g&#233;nie. Cette b&#233;n&#233;diction vous a prot&#233;g&#233; contre un grand danger ou indique que vous &#234;tes quelqu’un de sp&#233;cial aux yeux d’une divinit&#233;. Vous avez acc&#232;s aux traits de foi b&#233;ni et marque de naissance.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;83-84&lt;/td&gt;&lt;td&gt;&lt;b&gt;Fruit de la violence.&lt;/b&gt; Vous &#234;tes n&#233; d’une union violente et non consentie. Vous connaissez un de vos parents mais probablement pas l’autre. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; compte &#224; r&#233;gler et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; b&#226;tard.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;85&lt;/td&gt;&lt;td&gt;&lt;b&gt;N&#233; hors du temps.&lt;/b&gt; Vous &#234;tes n&#233; &#224; une autre &#233;poque, dans un pass&#233; ou un futur &#233;loign&#233;. Quelque chose vous a d&#233;plac&#233; hors de votre temps et les us et coutume de vos nouveaux contemporains vous paraissent bien &#233;tranges. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; &#233;rudit du Grand Au-del&#224;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;86-87&lt;/td&gt;&lt;td&gt;&lt;b&gt;N&#233; en servage.&lt;/b&gt; Vous &#234;tes n&#233; esclave ou serf. Vos parents &#233;taient probablement des esclaves, des serviteurs ou vous avez &#233;t&#233; vendu alors que vous &#233;tiez tr&#232;s jeune. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; vie de labeur.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;88&lt;/td&gt;&lt;td&gt;&lt;b&gt;Naissance maudite.&lt;/b&gt; &#192; votre naissance, une puissante entit&#233; fi&#233;lone a souill&#233; votre sang et vous a maudit pour faire de vous l’agent d’une sinistre proph&#233;tie. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; de lignage sang des fi&#233;lons et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Maudit.html&quot; title=&quot;Maudit&quot;&gt;Maudit&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;89-90&lt;/td&gt;&lt;td&gt;&lt;b&gt;Famille d&#233;shonor&#233;e.&lt;/b&gt; Vous &#234;tes dans une famille autrefois honor&#233;e autrefois mais d&#233;sormais tomb&#233;e en disgr&#226;ce. &#192; pr&#233;sent, ceux qui connaissent votre nom le m&#233;prisent et le diabolisent, voil&#224; pourquoi vous ne baissez jamais votre garde. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; r&#233;actif et aux dons d’histoire H&#233;ritage perdu et R&#233;demption.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91-92&lt;/td&gt;&lt;td&gt;&lt;b&gt;H&#233;ritier.&lt;/b&gt; Vous &#234;tes l’h&#233;ritier d’une famille ancienne au pass&#233; illustre. Riche ou de classe moyenne, peu importe, votre nom vaut deux fois plus que votre fortune. Vous avez acc&#232;s aux traits sociaux influent et parents fortun&#233;s.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;93-94&lt;/td&gt;&lt;td&gt;&lt;b&gt;Laiss&#233; pour mort.&lt;/b&gt; &#192; votre naissance, on vous a abandonn&#233; et laiss&#233; mourir mais, par un caprice du sort, vous avez surv&#233;cu. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; courageux, au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; sauvage et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Renaissance.html&quot; title=&quot;Renaissance&quot;&gt;Renaissance&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;95&lt;/td&gt;&lt;td&gt;&lt;b&gt;Marqu&#233; par les dieux.&lt;/b&gt; Une divinit&#233; a appos&#233; sa marque sur vous, que ce soit sur votre corps ou votre &#226;me. Vous avez acc&#232;s aux traits de foi marque de naissance et conduit sacr&#233; ainsi qu’au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Proph&#232;te.html&quot; title=&quot;Proph&#232;te&quot;&gt;Proph&#232;te&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96&lt;/td&gt;&lt;td&gt;&lt;b&gt;Impr&#233;gn&#233;.&lt;/b&gt; &#192; votre naissance, vous avez &#233;t&#233; expos&#233; &#224; une puissante source d’&#233;nergie divine. Vous avez acc&#232;s aux traits de foi conduit sacr&#233; et toucher sacr&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;97&lt;/td&gt;&lt;td&gt;&lt;b&gt;Sous le signe de la puissance.&lt;/b&gt; Vous &#234;tes n&#233; lors d’une conjonction particuli&#232;re ou &#224; une date plac&#233;e sous le signe de la puissance. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; talent magique, au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; charmeur et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; toucher sacr&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;98&lt;/td&gt;&lt;td&gt;&lt;b&gt;Enfant de la proph&#233;tie.&lt;/b&gt; On avait pr&#233;dit votre naissance, au plus tard &#224; la g&#233;n&#233;ration pr&#233;c&#233;dente mais peut-&#234;tre il y a des milliers d’ann&#233;es. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; naissance pr&#233;dite.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;99&lt;/td&gt;&lt;td&gt;&lt;b&gt;R&#233;incarn&#233;.&lt;/b&gt; Vous &#234;tes d&#233;j&#224; n&#233; de nombreuses fois et vous rena&#238;trez encore souvent, jusqu’&#224; ce que vous accomplissiez la t&#226;che &#224; laquelle vous &#234;tes destin&#233;. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; R&#233;incarn&#233; et aux dons d’histoire Renaissance et Pass&#233; oubli&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Pr&#233;sage.&lt;/b&gt; Les sages, les pr&#234;tres ou les magiciens de votre soci&#233;t&#233; ont d&#233;clar&#233; que votre naissance &#233;tait un signe d’une &#232;re ou d’un &#233;v&#233;nement &#224; venir. Peut-&#234;tre &#234;tes-vous l’annonciateur d’une grande promesse ou peut-&#234;tre celui d’une sombre &#233;poque. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; pr&#233;sage.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Profession des parents&lt;a class=&quot;headeranchor&quot; id=&quot;Profession_des_parents_10&quot; href=&quot;#Profession_des_parents_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En r&#232;gle g&#233;n&#233;rale, les deux parents sont issus de la m&#234;me cat&#233;gorie sociale. Ceci dit, m&#234;me si c’est rare, il arrive que des gens se marient en dehors de leur caste. Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#PROFESSIONDESPARENTS&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Profession des parents&lt;/a&gt;&quot; pour d&#233;terminer la profession principale de vos parents.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PROFESSIONDESPARENTS&quot; href=&quot;#PROFESSIONDESPARENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Profession des parents&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-05&lt;/td&gt;&lt;td&gt;&lt;b&gt;Esclaves.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; vie de labeur.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;06-25&lt;/td&gt;&lt;td&gt;&lt;b&gt;Serfs/paysans.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; mis&#233;reux.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;26-30&lt;/td&gt;&lt;td&gt;&lt;b&gt;Saltimbanques.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; talentueux.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;31-34&lt;/td&gt;&lt;td&gt;&lt;b&gt;Soldats.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; tacticien.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;35-37&lt;/td&gt;&lt;td&gt;&lt;b&gt;Marins.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; connaissance du monde.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;38-40&lt;/td&gt;&lt;td&gt;&lt;b&gt;Voleurs.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; enfant des rues.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-55&lt;/td&gt;&lt;td&gt;&lt;b&gt;Propri&#233;taires roturiers.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; enfant de la savane.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;56-70&lt;/td&gt;&lt;td&gt;&lt;b&gt;Commer&#231;ants.&lt;/b&gt; Vous avez acc&#232;s aux traits sociaux artisan et vie de labeur.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71-85&lt;/td&gt;&lt;td&gt;&lt;b&gt;Artisans.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; artisan.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;86-95&lt;/td&gt;&lt;td&gt;&lt;b&gt;Marchands.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; marchand.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Membres d’un clerg&#233; ou d’une secte.&lt;/b&gt; Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; enfant du temple.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Adopt&#233; par des parents d’une autre race&lt;a class=&quot;headeranchor&quot; id=&quot;Adopt&#233;_par_des_parents_d’une_autre_race_11&quot; href=&quot;#Adopt&#233;_par_des_parents_d’une_autre_race_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Si les d&#233;s ont d&#233;cid&#233; que vous avez &#233;t&#233; adopt&#233; par une famille qui n’est pas de la m&#234;me race que vous, consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#ADOPTEPARDESPARENTSDUNEAUTRERACE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Adopt&#233; par des parents d&#39;une autre race&lt;/a&gt;&quot; pour savoir quelles cr&#233;atures vous ont &#233;lev&#233;.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ADOPTEPARDESPARENTSDUNEAUTRERACE&quot; href=&quot;#ADOPTEPARDESPARENTSDUNEAUTRERACE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Adopt&#233; par des parents d’une autre race&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-05&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des dragons.&lt;/b&gt; Un dragon vous a &#233;lev&#233; pour des raisons connues de lui seul. Vous avez appris la langue et l’histoire des dragons, leur sagesse, leurs pouvoirs et leur puissance. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; de lignage sang des dragons et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; don pour la magie.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;06-10&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des f&#233;es.&lt;/b&gt; Vos parents adoptifs &#233;taient des cr&#233;atures f&#233;eriques comme des korreds, des pixies ou une dryade. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; charmeur et au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; don pour la magie.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11-13&lt;/td&gt;&lt;td&gt;&lt;b&gt;&#201;lev&#233; chez les morts.&lt;/b&gt; Votre parent adoptif est une cr&#233;ature morte-vivante, comme un spectre, un fant&#244;me, une liche ou un vampire. &#201;lev&#233; par une cr&#233;ature qui se nourrit de l’essence des vivants, vous avez grandi dans des couloirs vides en ruine, parmi les tombes et les cryptes. Personne ne sait pourquoi elle vous a recueilli. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; de lignage touch&#233; par la mort, au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; don pour la magie et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Aper&#231;u-De-Lau-Del&#224;.html&quot; title=&quot;Aper&#231;u de l&amp;#39;Au-del&#224;&quot;&gt;Aper&#231;u de l’Au-del&#224;&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;14-19&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des anges.&lt;/b&gt; Des anges ont assist&#233; &#224; votre naissance et vous ont emmen&#233; vivre avec eux au Paradis. Ces &#234;tres d’une dimension cosmique vous ont aid&#233; &#224; &#233;largir votre vision pour qu’elle englobe l’univers tout entier et pas seulement le monde. Vous savez que vos parents ang&#233;liques veillent sur vous, o&#249; que vous alliez. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; b&#233;ni.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;20-25&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des animaux.&lt;/b&gt; Quand vous avez &#233;t&#233; s&#233;par&#233; de vos parents biologiques, ce sont des b&#234;tes sauvages qui vous ont recueilli. Vous respectez les lois de la nature et vous avez d&#233;velopp&#233; un instinct de survie aigu, en plus d’adopter les habitudes d’un animal sp&#233;cifique. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; r&#233;silient et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Cœur-Animal.html&quot; title=&quot;Cœur animal&quot;&gt;Cœur animal&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;26-70&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des humano&#239;des civilis&#233;s.&lt;/b&gt; Vous avez grandi dans une communaut&#233; d’humano&#239;des civilis&#233;s (choisie par votre MJ) qui n’&#233;taient pas de la m&#234;me race que vous. Vos attitudes, vos croyances et vos valeurs refl&#232;tent celles de cette race, m&#234;me si votre v&#233;ritable nature ressurgit r&#233;guli&#232;rement. Vous avez acc&#232;s &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; de la race qui vous a &#233;lev&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71-95&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des humano&#239;des sauvages.&lt;/b&gt; Vous avez &#233;t&#233; &#233;lev&#233; par des humano&#239;des sauvages comme des orques, des kobolds, des gnolls, des troglodytes ou des hommes-l&#233;zards. Vos attitudes, vos croyances et vos valeurs refl&#232;tent celles de cette race, m&#234;me si votre v&#233;ritable nature ressurgit r&#233;guli&#232;rement. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; sauvage.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;Adopt&#233; par des fi&#233;lons.&lt;/b&gt; Vous avez &#233;t&#233; s&#233;par&#233; de vos parents naturels et &#233;lev&#233; par un fi&#233;lon qui vous a enseign&#233; la cruaut&#233; et la malveillance divine. Il vous a fa&#231;onn&#233; pour faire de vous un instrument destin&#233; &#224; corrompre les innocents. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Race.html&quot; title=&quot;Les traits de race&quot;&gt;trait racial&lt;/a&gt; de lignage Sang des fi&#233;lons et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Damn&#233;.html&quot; title=&quot;Damn&#233;&quot;&gt;Damn&#233;&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Noblesse&lt;a class=&quot;headeranchor&quot; id=&quot;Noblesse_12&quot; href=&quot;#Noblesse_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En tant que noble, vous avez des richesses, des privil&#232;ges et une influence qui d&#233;passent ceux des roturiers. Si votre personnage est de noble naissance (et vient d’une soci&#233;t&#233; o&#249; la noblesse respecte une hi&#233;rarchie traditionnelle), consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#NOBLESSE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Noblesse&lt;/a&gt;&quot; pour conna&#238;tre le rang de vos parents au sein de la classe dirigeante.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NOBLESSE&quot; href=&quot;#NOBLESSE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Noblesse&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;14%&quot;&gt;d100&lt;/td&gt;&lt;td WIDTH=&quot;86%&quot;&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-60&lt;/td&gt;&lt;td&gt;&lt;b&gt;Aristocratie terrienne.&lt;/b&gt; Vous &#234;tes l’enfant d’un seigneur ou d’une dame, c’est &#224; dire d’un noble poss&#233;dant des revenus, des terres h&#233;r&#233;ditaires (comme un manoir) et des titres. Vous avez probablement grandi dans un manoir o&#249; vos parents avaient des paysans &#224; leur service. Vos parents sont sous les ordres d’un baron, d’un comte ou d’un duc.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-78&lt;/td&gt;&lt;td&gt;&lt;b&gt;Chevalier.&lt;/b&gt; Vous &#234;tes l’enfant d’un chevalier, un noble poss&#233;dant des ch&#226;teaux, des titres et des terres. Votre famille est au service d’un seigneur auquel elle a jur&#233; fid&#233;lit&#233;. Il peut s’agir d’un baron, d’un comte ou d’un duc auquel elle apporte un soutien militaire. En tant qu’enfant de chevalier, vous pouvez devenir &#233;cuyer aupr&#232;s d’un autre chevalier lors de votre apprentissage pour atteindre ce rang.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;79-85&lt;/td&gt;&lt;td&gt;&lt;b&gt;Baron.&lt;/b&gt; Vous &#234;tes l’enfant d’un baron ou d’une baronne, un noble charg&#233; de g&#233;rer une r&#233;gion comprenant plusieurs petits manoirs &#224; son service. Vos parents re&#231;oivent leurs ordres directement de leur monarque et vous devez vous rendre &#224; la cour royale. Vous avez des ch&#226;teaux, des titres et des terres h&#233;r&#233;ditaires.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;86-91&lt;/td&gt;&lt;td&gt;&lt;b&gt;Comte.&lt;/b&gt; Vous &#234;tes l’enfant d’un comte ou d’une comtesse. Les membres de votre famille ont des titres, des terres et des ch&#226;teaux h&#233;r&#233;ditaires et vous faites partie des nobles les plus riches de votre pays. Les chevaliers et les nobles de bas rang vous doivent ob&#233;issance. Vos parents sont au service du monarque. Vous devez vous rendre &#224; la cour royale.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;92-96&lt;/td&gt;&lt;td&gt;&lt;b&gt;Duc.&lt;/b&gt; Vous &#234;tes l’enfant d’un duc ou d’une duchesse, les nobles les plus puissants du pays apr&#232;s la famille royale. Vos parents sont au service du monarque et occupent les positions les plus &#233;lev&#233;es de la cour. Vous avez des ch&#226;teaux, des terres et des titres en quantit&#233; et de nombreux seigneurs et chevaliers servent sous les ordres de vos parents.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;97-99&lt;/td&gt;&lt;td&gt;&lt;b&gt;Prince mineur.&lt;/b&gt; Vous &#234;tes l’enfant d’un prince ou d’une princesse et vous faites partie de la famille royale. Vous n’&#234;tes pas en premi&#232;re ligne pour la succession mais vous avez des richesses et un pouvoir impressionnants.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;100&lt;/td&gt;&lt;td&gt;&lt;b&gt;R&#233;gent.&lt;/b&gt; Vous &#234;tes un prince ou une princesse, l’enfant d’un monarque. Vous devez ob&#233;issance &#224; vos parents et &#224; nul autre. Peu de gens disposent d’autant de pouvoir et de richesses que vous et votre pr&#233;sence inspire le respect, sinon l’&#233;merveillement, parmi ceux qui s’agenouillent devant la couronne.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;3. &#201;v&#232;nement marquant de l&#39;enfance&lt;a class=&quot;headeranchor&quot; id=&quot;D_&#201;v&#232;nement_marquant_de_lenfance_16&quot; href=&quot;#D_&#201;v&#232;nement_marquant_de_lenfance_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
Pendant votre enfance, un &#233;v&#233;nement sp&#233;cial a eu une grande influence sur vous et vous a aid&#233; &#224; devenir ce que vous &#234;tes aujourd’hui. Consultez la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#EVENEMENTMARQUANTDELENFANCE&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;&#201;v&#232;nement marquant de l&#39;enfance&lt;/a&gt;&quot; pour d&#233;terminer cet &#233;v&#233;nement.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVENEMENTMARQUANTDELENFANCE&quot; href=&quot;#EVENEMENTMARQUANTDELENFANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&#201;v&#233;nement marquant de l’enfance&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;d100&lt;/td&gt;&lt;td&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-05&lt;/td&gt;&lt;td&gt;&lt;b&gt;Formation &#224; l’acad&#233;mie.&lt;/b&gt; Vous avez &#233;t&#233; dans une &#233;cole priv&#233;e o&#249; vous avez &#233;tudi&#233; diverses comp&#233;tences avant d’&#234;tre form&#233; dans votre m&#233;tier actuel. Que vous ayez &#233;t&#233; un &#233;l&#232;ve brillant ou que vous ayez abandonn&#233; vos &#233;tudes, cette &#233;cole a &#233;t&#233; votre foyer pendant une bonne partie de votre enfance. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; concentr&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;06-10&lt;/td&gt;&lt;td&gt;&lt;b&gt;Trahison.&lt;/b&gt; Vous avez &#233;t&#233; trahi par un ami ou un membre de votre famille en qui vous aviez confiance. Depuis, vous ne faites plus confiance &#224; personne et vous comptez seulement sur vos capacit&#233;s. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; m&#233;fiant.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11-15&lt;/td&gt;&lt;td&gt;&lt;b&gt;Pers&#233;cut&#233;.&lt;/b&gt; Quand vous &#233;tiez petit, vous &#233;tiez une victime, une proie facile pour les gens plus forts et plus rus&#233;s que vous. Ils vous frappaient d&#232;s qu’ils en avaient l’occasion, pour passer le temps. Ces mauvais traitements ont nourri une puissante soif de vengeance. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; brutalis&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;16-20&lt;/td&gt;&lt;td&gt;&lt;b&gt;Champion d’une comp&#233;tition.&lt;/b&gt; Vous vous &#234;tes distingu&#233; tr&#232;s jeune en remportant une comp&#233;tition : un concours d’escrime, une d&#233;monstration d’apprenti magicien, des paris avec de gros enjeux ou quelque chose d’aussi banal qu’un concours du plus gros mangeur. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; influent et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Champion.html&quot; title=&quot;Champion&quot;&gt;Champion&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-25&lt;/td&gt;&lt;td&gt;&lt;b&gt;D&#233;c&#232;s dans la famille.&lt;/b&gt; Vous avez &#233;t&#233; tr&#232;s affect&#233; par la perte d’un membre de votre famille dont vous &#233;tiez tr&#232;s proche, que ce se soit un de vos parents, un grand-parent, votre fr&#232;re ou soeur pr&#233;f&#233;r&#233;, une tante, un oncle ou un cousin. Cette mort vous a boulevers&#233; et vous ne vous en &#234;tes jamais vraiment remis. Vous avez acc&#232;s au don de combat r&#233;actif et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Refuser-La-Mort-Gc.html&quot; title=&quot;Refuser la mort (GC)&quot;&gt;Refuser la mort (GC)&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;26-30&lt;/td&gt;&lt;td&gt;&lt;b&gt;D&#233;c&#233;d&#233;.&lt;/b&gt; Vous &#234;tes mort, ou vous avez failli, au point que votre &#226;me a franchi la fronti&#232;re entre le royaume des morts et celui des vivants. Comme vous avez d&#233;j&#224; quitt&#233; une fois le domaine des vivants, vous portez un regard unique sur la vie et vous l’appr&#233;ciez peut-&#234;tre plus que quiconque, ou peut&#234;tre que vous rejetez &#224; pr&#233;sent tout ce qui vous para&#238;t trivial et que vous vous concentrez uniquement sur ce qui importe vraiment. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Foi.html&quot; title=&quot;Les traits de foi&quot;&gt;trait de foi&lt;/a&gt; absence de peur et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Renaissance.html&quot; title=&quot;Renaissance&quot;&gt;Renaissance&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;31-35&lt;/td&gt;&lt;td&gt;&lt;b&gt;Chute d’une puissance majeure.&lt;/b&gt; Pendant votre enfance, une ancienne puissance &#224; l’influence &#233;tendue s’est mise &#224; d&#233;cliner. Il peut s’agir d’un empire, d’une organisation majeure ou d’un simple gang, ou encore d’un roi bienveillant ou d’un dictateur mal&#233;fique. Vos premiers souvenirs sont teint&#233;s par cette puissance qui influait sur votre r&#233;gion, pour le meilleur ou pour le pire. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; connaissance du monde.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;36-40&lt;/td&gt;&lt;td&gt;&lt;b&gt;Mauvaises fr&#233;quentations.&lt;/b&gt; Durant votre jeunesse, vous avez &#233;t&#233; entour&#233; par des gens brutaux, mal&#233;fiques ou sadiques. Vous apparteniez peut-&#234;tre &#224; un gang, une guilde de voleurs ou une organisation peu recommandable. C’&#233;tait plus facile de c&#233;der &#224; leurs pressions et de faire ce qu’ils vous demandaient. Votre vision du monde est fauss&#233;e par votre ambigu&#239;t&#233; morale. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; enfant des rues.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-45&lt;/td&gt;&lt;td&gt;&lt;b&gt;Premier meurtre.&lt;/b&gt; Vous avez du sang sur les mains depuis votre enfance, lorsque vous avez pris la vie d’une autre cr&#233;ature pour la premi&#232;re fois. Que cet acte vous ait d&#233;go&#251;t&#233; ou vous ait ravi, il a &#233;t&#233; formateur. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; tueur et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Sang-Innocent.html&quot; title=&quot;Sang innocent&quot;&gt;Sang innocent&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;tr&gt;&lt;td&gt;46-50&lt;/td&gt;&lt;td&gt;&lt;b&gt;Premier amour bris&#233;.&lt;/b&gt; Votre premier amour &#233;tait exactement comme vous l’aviez imagin&#233;. Du moins, jusqu’&#224; ce que vous perdiez votre moiti&#233;, &#224; cause de la distance, d’un changement de perspective, d’un d&#233;c&#232;s, d’une diff&#233;rence de milieu ou encore de votre famille ou de la sienne. Certain disent que vous &#234;tes blas&#233; depuis ; vous, vous dites que cela vous a ouvert les yeux sur le v&#233;ritable fonctionnement du monde. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; connaissance du monde et vous lancez 1d12 au lieu d’un d20 dans la table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-3.html#RELATIONSAMOUREUSES&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 3: Conflits moraux, relations sociales et points faibles&quot;&gt;Relations amoureuses&lt;/a&gt;&quot;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;51-55&lt;/td&gt;&lt;td&gt;&lt;b&gt;Emprisonn&#233;.&lt;/b&gt; Vous avez vers&#233; dans la criminalit&#233; d&#232;s votre plus jeune &#226;ge. On vous a envoy&#233; en prison, puni et peut-&#234;tre expos&#233; en public en tant que criminel. Que vous soyez coupable ou non, cela vous a marqu&#233;. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; criminel. Consultez l’encadr&#233; &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;n&#233;rateur-Dhistorique,-&#201;tape-1.html#CRIMEETCHATIMENT&quot; title=&quot;G&#233;n&#233;rateur d&amp;#39;historique, &#201;tape 1: Pays natal, famille et enfance&quot;&gt;Crime et ch&#226;timent&lt;/a&gt;. Vous avez aussi acc&#232;s au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Lib&#233;rateur.html&quot; title=&quot;Lib&#233;rateur&quot;&gt;Lib&#233;rateur&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;56-60&lt;/td&gt;&lt;td&gt;&lt;b&gt;H&#233;ritage.&lt;/b&gt; Vous avez re&#231;u tr&#232;s jeune une grosse somme d’argent ou une belle propri&#233;t&#233;, vous mettant largement &#224; l’abri du besoin. Vous n’avez plus &#224; vous pr&#233;occuper des d&#233;penses quotidiennes et vous avez appris que l’argent peut tout acheter ou presque. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; parents fortun&#233;s.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-65&lt;/td&gt;&lt;td&gt;&lt;b&gt;Kidnapp&#233;.&lt;/b&gt; Pendant votre enfance, vous avez &#233;t&#233; victime d’un enl&#232;vement. Les auteurs du kidnapping peuvent &#234;tre des pirates, des esclavagistes, des voleurs en qu&#234;te d’une ran&#231;on, une puissante guilde d&#233;sireuse de faire chanter vos parents, un culte ou autre. Avant d’&#234;tre lib&#233;r&#233;, &#233;chang&#233; contre ran&#231;on ou de vous enfuir, vous avez eu un aper&#231;u des diverses facettes du monde du crime. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; argot et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Lib&#233;rateur.html&quot; title=&quot;Lib&#233;rateur&quot;&gt;Lib&#233;rateur&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;66-70&lt;/td&gt;&lt;td&gt;&lt;b&gt;Cadeau magique.&lt;/b&gt; Quand vous &#233;tiez enfant, vous avez trouv&#233;, vol&#233; ou on vous a donn&#233; un objet magique qui vous a conf&#233;r&#233; un pouvoir extraordinaire. Vous l’avez utilis&#233; pour faire le bien, le mal ou des blagues. Depuis, vous avez toujours &#233;t&#233; fascin&#233; par les objets magiques. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; talent magique.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71-75&lt;/td&gt;&lt;td&gt;&lt;b&gt;D&#233;sastre majeur.&lt;/b&gt; Pendant votre enfance, vous avez assist&#233; &#224; un d&#233;sastre majeur et vous avez surv&#233;cu. C’&#233;tait un incendie, une inondation, un tremblement de terre, une &#233;ruption volcanique ou une temp&#234;te qui a ray&#233; votre communaut&#233; de la carte, qu’il s’agisse d’un petit village, d’une grande ville ou d’une &#238;le enti&#232;re. Vous gagnez le &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; r&#233;silient et le don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Souvenir.html&quot; title=&quot;Souvenir&quot;&gt;Souvenir&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;76-80&lt;/td&gt;&lt;td&gt;&lt;b&gt;Mentor/m&#233;c&#233;nat.&lt;/b&gt; Un mentor ou un m&#233;c&#232;ne s’est int&#233;ress&#233; &#224; vous et vous a propos&#233; de vous entra&#238;ner ou de vous parrainer. Les motivations de cette personne ne sont pas forc&#233;ment claires mais sans elle, vous ne seriez pas celui que vous &#234;tes aujourd’hui. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; mentor.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-85&lt;/td&gt;&lt;td&gt;&lt;b&gt;Rencontre avec une cr&#233;ature fantastique.&lt;/b&gt; Vous avez rencontr&#233; une cr&#233;ature magique alors que vous n’&#233;tiez encore qu’un enfant. C’&#233;tait peut-&#234;tre un dragon, une licorne, un g&#233;nie, un pixie ou une cr&#233;ature similaire. Cet &#234;tre vous a enseign&#233; une grande le&#231;on ou un tour de magie. Depuis cette rencontre qui a boulevers&#233; votre vie, vous n’&#233;tiez plus comme les autres enfants. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Magie.html&quot; title=&quot;Les traits de magie&quot;&gt;trait de magie&lt;/a&gt; adepte dou&#233;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;86-90&lt;/td&gt;&lt;td&gt;&lt;b&gt;Enfance ordinaire.&lt;/b&gt; Vous avez v&#233;cu une enfance des plus ordinaires, sans b&#233;n&#233;diction ni catastrophe particuli&#232;re, ce qui contraste avec votre vie d’aventurier. Vous avez pass&#233; votre enfance &#224; attendre d’&#234;tre assez grand pour changer le d&#233;cor morne de votre vie mais maintenant que vous avez grandi, vous regrettez r&#233;guli&#232;rement ces jours tranquilles o&#249; rien ne se passait jamais. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Sociaux.html&quot; title=&quot;Les traits sociaux&quot;&gt;trait social&lt;/a&gt; ordinaire.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91-95&lt;/td&gt;&lt;td&gt;&lt;b&gt;Pillards.&lt;/b&gt; Une horde de pillards a attaqu&#233; votre communaut&#233; et tu&#233; plusieurs personnes. C’&#233;tait peut-&#234;tre une tribu d’humano&#239;des f&#233;roces ou l’arm&#233;e d’une nation civilis&#233;e. Quoi qu’il en soit, vous nourrissez une profonde rancœur &#224; l’&#233;gard d’une faction, d’une race ou d’un pays. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-De-Combat.html&quot; title=&quot;Les traits de combat&quot;&gt;trait de combat&lt;/a&gt; compte &#224; r&#233;gler et aux dons d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Tueur-Dennemis.html&quot; title=&quot;Tueur d&amp;#39;ennemis&quot;&gt;Tueur d’ennemis&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Vengeance.html&quot; title=&quot;Vengeance&quot;&gt;Vengeance&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;96-100&lt;/td&gt;&lt;td&gt;&lt;b&gt;En guerre.&lt;/b&gt; Votre enfance s’est d&#233;roul&#233;e sur fond de conflit militaire majeur, ce qui vous a profond&#233;ment marqu&#233;. Vous avez l’habitude d’&#234;tre rationn&#233;, de vivre en territoire occup&#233; et de d&#233;m&#233;nager sans cesse. Vous avez perdu des gens au cours de la guerre, dont des membres de votre famille. Vous avez acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Traits-R&#233;gionaux.html&quot; title=&quot;Les traits r&#233;gionaux&quot;&gt;trait r&#233;gional&lt;/a&gt; enfant vagabond et au don d’histoire &lt;a class=&quot;pagelink&quot; href=&quot;Refuser-La-Mort-Gc.html&quot; title=&quot;Refuser la mort (GC)&quot;&gt;Refuser la mort (GC)&lt;/a&gt;.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CRIMEETCHATIMENT&quot; href=&quot;#CRIMEETCHATIMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Encadr&#233; : Crime et ch&#226;timent&lt;a class=&quot;headeranchor&quot; id=&quot;Encadr&#233;_:_Crime_et_ch&#226;timent_13&quot; href=&quot;#Encadr&#233;_:_Crime_et_ch&#226;timent_13&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Si vous avez le trait social criminel, consultez la table &quot;Crime&quot; pour d&#233;terminer de quel crime vous avez &#233;t&#233; accus&#233; ou reconnu coupable. Ensuite, reportez-vous &#224; la table &quot;Ch&#226;timent&quot; pour voir le type de ch&#226;timent que vous avez re&#231;u (ou que vous devez recevoir) pour avoir &#233;t&#233; d&#233;clar&#233; coupable.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;Crime&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;d100&lt;/td&gt;&lt;td&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-10&lt;/td&gt;&lt;td&gt;Adult&#232;re&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11-20&lt;/td&gt;&lt;td&gt;Incendie criminel&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-30&lt;/td&gt;&lt;td&gt;Cambriolage&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;31-40&lt;/td&gt;&lt;td&gt;H&#233;r&#233;sie&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-50&lt;/td&gt;&lt;td&gt;Offense mineur (lois somptuaires)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;51-60&lt;/td&gt;&lt;td&gt;Meurtre&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-70&lt;/td&gt;&lt;td&gt;R&#233;bellion/trahison&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71-80&lt;/td&gt;&lt;td&gt;Vol&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-90&lt;/td&gt;&lt;td&gt;Contrebande&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91-100&lt;/td&gt;&lt;td&gt;Usage ill&#233;gal de la magie&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;Ch&#226;timent&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;d100&lt;/td&gt;&lt;td&gt;R&#233;sultat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;01-10&lt;/td&gt;&lt;td&gt;Bastonnade&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11-20&lt;/td&gt;&lt;td&gt;Marquage au fer rouge&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;21-30&lt;/td&gt;&lt;td&gt;Exil&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;31-40&lt;/td&gt;&lt;td&gt;Amende&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;41-50&lt;/td&gt;&lt;td&gt;Emprisonnement&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;51-60&lt;/td&gt;&lt;td&gt;Pilori&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;61-70&lt;/td&gt;&lt;td&gt;Torture&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;71-80&lt;/td&gt;&lt;td&gt;Ordalie, &#233;preuve par le combat&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;81-90&lt;/td&gt;&lt;td&gt;Ordalie, &#233;preuve par le feu&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;91-100&lt;/td&gt;&lt;td&gt;Ordalie, &#233;preuve par l’eau&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
